use vstd::prelude::*;

verus! {

fn concatenate(a: Vec<f32>, b: Vec<f32>) -> (res: Vec<f32>)
    ensures
        // (1) length is sum of lengths
        res.len() == a.len() + b.len(),

        // (2) prefix equals `a`
        forall|i: int|
            0 <= i < a.len() ==> res[i] == a[i],

        // (3) suffix equals `b`
        forall|j: int|
            0 <= j < b.len() ==> res[a.len() + j] == b[j],
{
    let mut res: Vec<f32> = Vec::new();
    let a_len = a.len();

    let mut i: usize = 0;
    while i < a.len()
        invariant
            res.len() == i,
            forall|k: int| 0 <= k < i ==> res[k] == a[k],
        decreases a.len() - i,
    {
        res.push(a[i]);
        i += 1;
    }

    let mut j: usize = 0;
    while j < b.len()
        invariant
            res.len() == a_len + j,
            forall|k: int| 0 <= k < a_len ==> res[k] == a[k],
            forall|t: int| 0 <= t < j ==> res[a_len + t] == b[t],
        decreases b.len() - j,
    {
        res.push(b[j]);
        j += 1;
    }

    res
}

} // verus!

